package dev.gbppimentel.zzz;
import java.io.File;import java.nio.file.Files;import org.json.*;
public final class DailyHistoryTest {
 static int checks;static void check(boolean v){if(!v)throw new AssertionError("Daily history "+checks);checks++;}
 public static void main(String[]args)throws Exception{File dir=Files.createTempDirectory("eridu-history-test").toFile();try{long at=java.time.Instant.parse("2026-11-24T19:00:00Z").toEpochMilli();String a="1000000001",b="1000000002";check(DailyHistory.summary(dir,a,at).getBoolean("errandsAvailable"));DailyHistory.save(dir,a,new JSONObject().put("lastTriggeredAt",at).put("lastState","stopped"));check(DailyHistory.summary(dir,a,at+1000).getBoolean("errandsAvailable"));check(DailyHistory.summary(dir,a,at+1000).getLong("lastTriggeredAt")==at);check(DailyHistory.summary(dir,b,at).getLong("lastTriggeredAt")==0);JSONObject h=DailyHistory.read(dir,a).put("errandsCompletedAt",at);DailyHistory.save(dir,a,h);check(DailyHistory.summary(dir,a,at+1000).getBoolean("errandsAvailable"));JSONObject tasks=new JSONObject();for(String key:new String[]{"coffee","draw","store","temple"})tasks.put(key,new JSONObject().put("at",at));h.put("tasks",tasks);DailyHistory.save(dir,a,h);check(DailyHistory.summary(dir,a,at+1000).getBoolean("errandsAvailable"));tasks.put("rewards",new JSONObject().put("at",at));DailyHistory.save(dir,a,h);check(!DailyHistory.summary(dir,a,at+1000).getBoolean("errandsAvailable"));check(DailyHistory.summary(dir,a,at+1000).getJSONObject("verifiedTasks").getBoolean("coffee"));check(!DailyHistory.summary(dir,a,at+7200000).getJSONObject("verifiedTasks").getBoolean("coffee"));check(!DailyHistory.summary(dir,b,at).getJSONObject("verifiedTasks").getBoolean("coffee"));check(DailyHistory.summary(dir,a,at+7200000).getBoolean("errandsAvailable"));DailyHistory.save(dir,b,new JSONObject().put("lastTriggeredAt",at+5));check(DailyHistory.read(dir,a).optLong("errandsCompletedAt")==at);System.out.println(checks+" scoped daily history checks passed");}finally{for(File f:dir.listFiles())f.delete();dir.delete();}}
}
